// Map the PhonePe callback + your cart context onto the CRM order payload.
// Adjust the left-hand side to match what your checkout actually stores.

const body = $json.body ?? $json;

// PhonePe reports state as COMPLETED / FAILED / PENDING.
const state = (body.state ?? body.code ?? '').toString().toUpperCase();
const paymentStatus =
  state.includes('SUCCESS') || state.includes('COMPLETED') ? 'SUCCESS'
  : state.includes('FAIL') || state.includes('ERROR') ? 'FAILED'
  : 'PENDING';

// merchantOrderId is the reference YOU generated before redirecting to PhonePe.
// It is the idempotency anchor — the CRM will never create two orders for it.
const orderId = body.merchantOrderId ?? body.merchantTransactionId;

if (!orderId) {
  throw new Error('No merchantOrderId on the callback — cannot make this idempotent');
}

// Amounts arrive in paise.
const totalPrice = Number(body.amount ?? 0) / 100;

return [{
  json: {
    phone: body.metaInfo?.udf1 ?? body.phone,
    customerName: body.metaInfo?.udf2 ?? body.customerName ?? undefined,
    orderId,
    cookieType: body.metaInfo?.udf3 ?? body.cookieType,
    quantity: Number(body.metaInfo?.udf4 ?? body.quantity ?? 1),
    toppings: body.toppings ?? [],
    deliveryDate: body.deliveryDate ?? undefined,
    deliveryAddress: body.deliveryAddress ?? undefined,
    totalPrice,
    paymentStatus,
    paymentTransactionId: body.transactionId ?? body.providerReferenceId ?? orderId,
    paidAt: paymentStatus === 'SUCCESS' ? new Date().toISOString() : undefined,
    gateway: 'phonepe',
    paymentMethod: body.paymentInstrument?.type ?? 'UPI'
  }
}];
